window.AUTH=window.AUTH||{};window.AUTH["24-724"]={"d":"24-724","id":"2025/24-724","n":"Hain Celestial Group, Inc. v. Palmquist","briefs":[{"k":"petitioner","label":"Brief of petitioners The Hain Celestial Group, Inc., Whole Foods Market, Inc.","date":"2025-06-27","url":"https://www.supremecourt.gov/DocketPDF/24/24-724/364036/20250627145559504_24-724%20Brief%20of%20Petitioners.pdf","side":"pet","n":35},{"k":"respondent","label":"Brief of respondents Sarah Palmquist, Individually and as Next Friend of E.P., a Minor, et al.","date":"2025-08-11","url":"https://www.supremecourt.gov/DocketPDF/24/24-724/369407/20250811163207161_resp.%20merits%20brief%20-%20Hain%20Celestial%20v.%20Palmquist%20-%20No.%2024-724.pdf","side":"res","n":67},{"k":"reply","label":"Reply of petitioners The Hain Celestial Group, Inc., et al.","date":"2025-09-10","url":"https://www.supremecourt.gov/DocketPDF/24/24-724/374297/20250910160916509_24-724%20Reply%20Brief.pdf","side":"pet","n":23}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/607us2r14_1a72.pdf","tr":true,"items":[{"t":"case","label":"Amstadt v. U.S. Brass Corp.","cite":"919 S.W.2d 644","y":1996,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/919/644/","by":{"0":"27"}},{"t":"case","label":"Anderson v. Watt","cite":"138 U.S. 694","y":1891,"id":"scdb/1890-148","sc":1,"by":{"0":"13","1":"3, 32"}},{"t":"case","label":"Caterpillar, Inc. v. Lewis","cite":"519 U.S. 61","y":1996,"id":"1996/95-1263","sc":1,"by":{"0":"12–16, 18, 19, 32","1":"4, 10, 12, 15, 18, 20-22, 24-33, 35-36, 40, 42","2":"6, 12, 14"},"q":[{"src":"brief","b":0,"text":"would impose unnecessary and wasteful burdens on the parties, judges, and other litigants waiting for judicial attention.","cite":"519 U.S. at 76"},{"src":"brief","b":0,"text":"erroneous removal need not cause the destruction of [the] final judgment.","cite":"519 U.S. at 73"},{"src":"brief","b":1,"text":"Congress has constantly authorized the federal courts to exercise jurisdiction based on the diverse citizenship of parties.","cite":"519 U.S. 61, 68"},{"src":"brief","b":1,"text":"cases in which the citizenship of each plaintiff is diverse from the citizenship of each defendant.","cite":"519 U.S. at 68"},{"src":"brief","b":2,"text":"considerations of finality, efficiency, and economy","cite":"519 U.S. at 75"},{"src":"brief","b":2,"text":"The same may be said of the remand to state court [Respondents] seek[] here.","cite":"519 U.S. at 76"}]},{"t":"case","label":"Chesapeake & O. R. Co. v. Cockrell","cite":"232 U.S. 146","y":1914,"id":"scdb/1913-261","sc":1,"by":{"0":"4","1":"16"},"q":[{"src":"brief","b":1,"text":"state[s] a good cause of action against the resident defendants.","cite":"232 U.S. 146, 152"}]},{"t":"case","label":"Curley v. Brignoli, Curley & Roberts Assocs.","cite":"915 F.2d 81","y":1990,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/915/81/","by":{"0":"31"},"q":[{"src":"brief","b":0,"text":"[a]fter trial, considerations of efficiency of course include the fact that the time and expense of a trial have already been spent.","cite":"915 F.2d 81, 91"}]},{"t":"case","label":"Erie R. Co. v. Tompkins","cite":"304 U.S. 64","y":1938,"id":"1900-1940/304us64","sc":1,"by":{"0":"30"},"q":[{"src":"argument","who":"Mr. Post","text":"And so it is true that as the case was tried, it was tried solely based on the quality of the product, but that was an artifact of the erroneous ruling, an erroneous Erie guess made by the district court about the content of state law that should have been a determination made by the state courts consistent with the congressional scheme."}]},{"t":"case","label":"Gorfinkle v. U.S. Airways, Inc.","cite":"431 F.3d 19","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/431/19/","by":{"0":"30, 31","1":"43","2":"19"}},{"t":"case","label":"Grice v. CVR Energy, Inc.","cite":"921 F.3d 966","y":2019,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/921/966/","by":{"0":"31","1":"43"}},{"t":"case","label":"Grupo Dataflux v. Atlas Glob. Grp., L.P.","cite":"541 U.S. 567","y":2004,"id":"2003/02-1689","sc":1,"by":{"0":"13, 14, 19, 21, 23","1":"3, 14, 19, 30-35","2":"8, 10, 16, 17"},"q":[{"src":"brief","b":0,"text":"[w]here there is no change of party, a jurisdiction depending on the condition of the party is governed by that condition, as it was at the commencement of the suit.","cite":"541 U.S. 567, 574"},{"src":"brief","b":0,"text":"policy goal of minimizing litigation over jurisdiction.","cite":"541 U.S. at 518"},{"src":"brief","b":1,"text":"by whatever route a case arrives in federal court.","cite":"541 U.S. 567, 593"},{"src":"brief","b":1,"text":"regardless of the costs it imposes.","cite":"541 U.S. at 571"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"the PstaategofefacPts rthoatoexfisPtedeant tdheitnimge oPf fulinbg.","cite":"541 U. S. 567, 571"}]},{"t":"case","label":"Hanna v. Plumer","cite":"380 U.S. 460","y":1965,"id":"1964/171","sc":1,"by":{"0":"30"}},{"t":"case","label":"Helena Chem. Co. v. Cox","cite":"664 S.W.3d 66","y":2023,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/664/66/","by":{"0":"31"},"q":[{"src":"brief","b":0,"text":"scientific knowledge of the harmful level of exposure to a chemical, plus knowledge that the plaintiff was exposed to such quantities.","cite":"664 S.W.3d 66, 76"}]},{"t":"case","label":"Highland Cap. Mgmt. L.P. v. Schneider","cite":"198 F. App’x 41","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/198/41/","by":{"0":"30","1":"43","2":"19"}},{"t":"case","label":"Ingram v. CSX Transp., Inc.","cite":"146 F.3d 858","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/146/858/","by":{"0":"30, 31","1":"43","2":"19"}},{"t":"case","label":"Lakes of Rosehill Homeowners Ass’n, Inc. v. Jones","cite":"552 S.W.3d 414","y":2018,"court":"Tex. App.","url":"https://www.courtlistener.com/c/S.W.3d/552/414/","by":{"0":"27","1":"46"}},{"t":"case","label":"Martinez v. Duke Energy Corp.","cite":"130 F. App’x 629","y":2005,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/130/629/","by":{"0":"31","1":"43"}},{"t":"case","label":"Mullaney v. Anderson","cite":"342 U.S. 415","y":1952,"id":"scdb/1951-045","sc":1,"by":{"0":"28"},"q":[{"src":"brief","b":0,"text":"affected the course of the litigation,","cite":"342 U.S. 415, 417"}]},{"t":"case","label":"Newman Green, Inc. v. Alfonzo-Larrain","cite":"1987 WL 5232","y":1987,"court":"N.D. Ill. Jan. 7","by":{"0":"27"},"q":[{"src":"argument","who":"Ms. Harrington","text":"Finally, if this Court harbors doubts that the district court had jurisdiction to enter a final judgment, the decision in Newman-Green makes clear that the final judgment should be preserved by dismissing Whole Foods now."},{"src":"argument","who":"Ms. Harrington","text":"That is how this Court has talked about it in cases like Caterpillar and Newman-Green, and we picked up on that in the briefing. But, when you're talking about fraudulent joinder, it might not even be the best framing because, when you're talking about fraudulent joinder, there isn't an erroneous assertion of jurisdiction ever in the way that there was in cases like Caterpillar because the non-diverse defendant is just treated as not a real party to the case and there's never an assertion of federal jurisdiction over the claim against that non-diverse party."},{"src":"argument","who":"Ms. Harrington","text":"No, but, I mean, that would be Newman-Green. In Caterpillar, the -- the non-diverse defendant had already -- was already out of the case before a final judgment was entered."}]},{"t":"case","label":"Newman-Green, Inc. v. Alfonzo-Larrain","cite":"832 F.2d 417","y":1987,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/832/417/","by":{"0":"29"}},{"t":"case","label":"Newman-Green, Inc. v. Alfonzo-Larrain","cite":"854 F.2d 916","y":1988,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/854/916/","by":{"0":"27"}},{"t":"case","label":"Newman-Green, Inc. v. Alfonzo-Larrain","cite":"490 U.S. 826","y":1989,"id":"1988/88-774","sc":1,"by":{"0":"16, 22–24, 26–29","1":"38-45, 47-48","2":"1, 6, 14, 17, 18, 19, 20"},"q":[{"src":"brief","b":1,"text":"appellate courts possess[ ] the authority to grant motions to dismiss dispensable nondiverse parties.","cite":"490 U.S. at 836"},{"src":"brief","b":1,"text":"carefully consider whether the dismissal of a nondiverse party will prejudice any of the parties in the litigation.","cite":"490 U.S. at 838"},{"src":"brief","b":2,"text":"unnecessary and wasteful burdens on the parties, judges, and other litigants waiting for judicial attention","cite":"490 U.S. at 836"},{"src":"brief","b":2,"text":"after years of litigation would impose unnecessary and wasteful burdens on the parties, judges, and other litigants waiting for judicial attention.","cite":"490 U.S. at 836"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"appellate courts . . . ha[ve] dismissed dispensable nondiverse parties in order to preserve jurisdiction as to diverse parties","cite":"490 U. S. 826, 834–836"}]},{"t":"case","label":"Provident Tradesmens Bank & Tr. Co. v. Patterson","cite":"390 U.S. 102","y":1968,"id":"1967/28","sc":1,"by":{"0":"29, 32"}},{"t":"case","label":"Royal Canin U.S.A., Inc. v. Wullschleger","cite":"604 U.S. 22","y":2025,"id":"2024/23-677","sc":1,"by":{"0":"12, 13, 15","1":"3, 14, 18, 21, 26, 33, 37, 44-45"},"q":[{"src":"brief","b":0,"text":"concerns only the actual state of things relevant to jurisdiction—meaning, the facts on the ground,","cite":"604 U.S. at 36 n.5"},{"src":"brief","b":0,"text":"can either destroy or create jurisdiction,","cite":"604 U.S. at 37"},{"src":"brief","b":1,"text":"[l]imited first by the Constitution, to only the kinds of ‘Cases’ and ‘Controversies’ listed in Article III.","cite":"604 U.S. 22, 26"},{"src":"brief","b":1,"text":"The plaintiff is ‘the master of the complaint,’ and therefore controls much about her suit.","cite":"604 U.S. at 35"},{"src":"argument","who":"Justice Kagan","text":"You know, last year, we talked about 36 -- 1367(c) in Royal Canin, and we talked about how 1367(c) says when you have a federal claim and a supplemental state claim and the federal claims drop out --"},{"src":"argument","who":"Justice Kagan","text":"And the way Royal Canin talks about that is that -- is because the federal claims have not dropped out for good. They can re- emerge on appeal."},{"src":"argument","who":"Justice Kagan","text":"It's saying, in both cases, the thing that created the federal jurisdiction is gone, and the question is, does the -- the federal court still have jurisdiction over what remains? And -- and what Royal Canin says is, yes, because the -- the thing that created federal jurisdiction can still come back."}]},{"t":"case","label":"St. Paul Mercury Indem. Co. v. Red Cab Co.","cite":"303 U.S. 283","y":1938,"id":"scdb/1937-104","sc":1,"by":{"0":"13"}},{"t":"case","label":"Temple v. Synthes Corp.","cite":"498 U.S. 5","y":1990,"id":"1990/90-295","sc":1,"by":{"0":"26","1":"46"}},{"t":"case","label":"Travis v. Irby","cite":"326 F.3d 644","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/326/644/","by":{"0":"4"},"q":[{"src":"brief","b":0,"text":"establish a cause of action against the non-diverse party in state court,","cite":"326 F.3d 644, 647"}]},{"t":"case","label":"Weber v. GE Grp. Life Assur. Co.","cite":"541 F.3d 1002","y":2008,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/541/1002/","by":{"0":"29","1":"43"}},{"t":"const","label":"Article III, Section 2","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects. In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make. The Trial of all Crimes, except in Cases of Impeachment, shall be by Jury; and such Trial shall be held in the State where the said Crimes shall have been committed; but when not committed within any State, the Trial shall be at such Place or Places as the Congress may by Law have directed.","by":{"0":"1, 11"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","subs":["(a)","(a)(1)"],"stext":{"head":"§1332. Diversity of citizenship; amount in controversy; costs","paras":[[0,"(a) The district courts shall have original jurisdiction of all civil actions where the matter in controversy exceeds the sum or value of $75,000, exclusive of interest and costs, and is between—"],[1,"(1) citizens of different States;"],[1,"(2) citizens of a State and citizens or subjects of a foreign state, except that the district courts shall not have original jurisdiction under this subsection of an action between citizens of a State and citizens or subjects of a foreign state who are lawfully admitted for permanent residence in the United States and are domiciled in the same State;"],[1,"(3) citizens of different States and in which citizens or subjects of a foreign state are additional parties; and"],[1,"(4) a foreign state, defined in section 1603(a) of this title, as plaintiff and citizens of a State or of different States."],[0,"(b) Except when express provision therefor is otherwise made in a statute of the United States, where the plaintiff who files the case originally in the Federal courts is finally adjudged to be entitled to recover less than the sum or value of $75,000, computed without regard to any setoff or counterclaim to which the defendant may be adjudged to be entitled, and exclusive of interest and costs, the district court may deny costs to the plaintiff and, in addition, may impose costs on the plaintiff."],[0,"(c) For the purposes of this section and section 1441 of this title—"],[1,"(1) a corporation shall be deemed to be a citizen of every State and foreign state by which it has been incorporated and of the State or foreign state where it has its principal place of business, except that in any direct action against the insurer of a policy or contract of liability insurance, whether incorporated or unincorporated, to which action the insured is not joined as a party-defendant, such insurer shall be deemed a citizen of—"],[2,"(A) every State and foreign state of which the insured is a citizen;"],[2,"(B) every State and foreign state by which the insurer has been incorporated; and"],[2,"(C) the State or foreign state where the insurer has its principal place of business; and"],[1,"(2) the legal representative of the estate of a decedent shall be deemed to be a citizen only of the same State as the decedent, and the legal representative of an infant or incompetent shall be deemed to be a citizen only of the same State as the infant or incompetent."],[0,"(d)(1) In this subsection—"],[1,"(A) the term \"class\" means all of the class members in a class action;"],[1,"(B) the term \"class action\" means any civil action filed under rule 23 of the Federal Rules of Civil Procedure or similar State statute or rule of judicial procedure authorizing an action to be brought by 1 or more representative persons as a class action;"],[1,"(C) the term \"class certification order\" means an order issued by a court approving the treatment of some or all aspects of a civil action as a class action; and"],[1,"(D) the term \"class members\" means the persons (named or unnamed) who fall within the definition of the proposed or certified class in a class action."],[0,"(2) The district courts shall have original jurisdiction of any civil action in which the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs, and is a class action in which—"],[1,"(A) any member of a class of plaintiffs is a citizen of a State different from any defendant;"],[1,"(B) any member of a class of plaintiffs is a foreign state or a citizen or subject of a foreign state and any defendant is a citizen of a State; or"],[1,"(C) any member of a class of plaintiffs is a citizen of a State and any defendant is a foreign state or a citizen or subject of a foreign state."],[0,"(3) A district court may, in the interests of justice and looking at the totality of the circumstances, decline to exercise jurisdiction under paragraph (2) over a class action in which greater than one-third but less than two-thirds of the members of all proposed plaintiff classes in the aggregate and the primary defendants are citizens of the State in which the action was originally filed based on consideration of—"],[1,"(A) whether the claims asserted involve matters of national or interstate interest;"],[1,"(B) whether the claims asserted will be governed by laws of the State in which the action was originally filed or by the laws of other States;"],[1,"(C) whether the class action has been pleaded in a manner that seeks to avoid Federal jurisdiction;"],[1,"(D) whether the action was brought in a forum with a distinct nexus with the class members, the alleged harm, or the defendants;"],[1,"(E) whether the number of citizens of the State in which the action was originally filed in all proposed plaintiff classes in the aggregate is substantially larger than the number of citizens from any other State, and the citizenship of the other members of the proposed class is dispersed among a substantial number of States; and"],[1,"(F) whether, during the 3-year period preceding the filing of that class action, 1 or more other class actions asserting the same or similar claims on behalf of the same or other persons have been filed."],[0,"(4) A district court shall decline to exercise jurisdiction under paragraph (2)—"],[1,"(A)(i) over a class action in which—"],[2,"(I) greater than two-thirds of the members of all proposed plaintiff classes in the aggregate are citizens of the State in which the action was originally filed;"],[2,"(II) at least 1 defendant is a defendant—"],[3,"(aa) from whom significant relief is sought by members of the plaintiff class;"],[3,"(bb) whose alleged conduct forms a significant basis for the claims asserted by the proposed plaintiff class; and"],[3,"(cc) who is a citizen of the State in which the action was originally filed; and"],[2,"(III) principal injuries resulting from the alleged conduct or any related conduct of each defendant were incurred in the State in which the action was originally filed; and"],[1,"(ii) during the 3-year period preceding the filing of that class action, no other class action has been filed asserting the same or similar factual allegations against any of the defendants on behalf of the same or other persons; or"],[1,"(B) two-thirds or more of the members of all proposed plaintiff classes in the aggregate, and the primary defendants, are citizens of the State in which the action was originally filed."],[0,"(5) Paragraphs (2) through (4) shall not apply to any class action in which—"],[1,"(A) the primary defendants are States, State officials, or other governmental entities against whom the district court may be foreclosed from ordering relief; or"],[1,"(B) the number of members of all proposed plaintiff classes in the aggregate is less than 100."],[0,"(6) In any class action, the claims of the individual class members shall be aggregated to determine whether the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs."],[0,"(7) Citizenship of the members of the proposed plaintiff classes shall be determined for purposes of paragraphs (2) through (6) as of the date of filing of the complaint or amended complaint, or, if the case stated by the initial pleading is not subject to Federal jurisdiction, as of the date of service by plaintiffs of an amended pleading, motion, or other paper, indicating the existence of Federal jurisdiction."],[0,"(8) This subsection shall apply to any class action before or after the entry of a class certification order by the court with respect to that action."],[0,"(9) Paragraph (2) shall not apply to any class action that solely involves a claim—"],[1,"(A) concerning a covered security as defined under 16(f)(3) 1 of the Securities Act of 1933 (15 U.S.C. 78p(f)(3) 2) and section 28(f)(5)(E) of the Securities Exchange Act of 1934 (15 U.S.C. 78bb(f)(5)(E));"],[1,"(B) that relates to the internal affairs or governance of a corporation or other form of business enterprise and that arises under or by virtue of the laws of the State in which such corporation or business enterprise is incorporated or organized; or"],[1,"(C) that relates to the rights, duties (including fiduciary duties), and obligations relating to or created by or pursuant to any security (as defined under section 2(a)(1) of the Securities Act of 1933 (15 U.S.C. 77b(a)(1)) and the regulations issued thereunder)."],[0,"(10) For purposes of this subsection and section 1453, an unincorporated association shall be deemed to be a citizen of the State where it has its principal place of business and the State under whose laws it is organized."],[0,"(11)(A) For purposes of this subsection and section 1453, a mass action shall be deemed to be a class action removable under paragraphs (2) through (10) if it otherwise meets the provisions of those paragraphs."],[0,"(B)(i) As used in subparagraph (A), the term \"mass action\" means any civil action (except a civil action within the scope of section 1711(2)) in which monetary relief claims of 100 or more persons are proposed to be tried jointly on the ground that the plaintiffs' claims involve common questions of law or fact, except that jurisdiction shall exist only over those plaintiffs whose claims in a mass action satisfy the jurisdictional amount requirements under subsection (a)."],[0,"(ii) As used in subparagraph (A), the term \"mass action\" shall not include any civil action in which—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1332?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 4, 12, 18","1":"4, 15"},"q":[{"src":"brief","b":1,"text":"original jurisdiction of all civil actions where the matter in controversy exceeds the sum or value of $75,000, exclusive of interest and costs, and is between . . . citizens of different States.","cite":"28 U.S.C. § 1332(a)(1)"}]},{"t":"usc","label":"28 U.S.C. § 1441","url":"https://www.law.cornell.edu/uscode/text/28/1441","subs":["(a)"],"stext":{"head":"§1441. Removal of civil actions","paras":[[0,"(a) Generally.—Except as otherwise expressly provided by Act of Congress, any civil action brought in a State court of which the district courts of the United States have original jurisdiction, may be removed by the defendant or the defendants, to the district court of the United States for the district and division embracing the place where such action is pending."],[0,"(b) Removal Based on Diversity of Citizenship.—(1) In determining whether a civil action is removable on the basis of the jurisdiction under section 1332(a) of this title, the citizenship of defendants sued under fictitious names shall be disregarded."],[0,"(2) A civil action otherwise removable solely on the basis of the jurisdiction under section 1332(a) of this title may not be removed if any of the parties in interest properly joined and served as defendants is a citizen of the State in which such action is brought."],[0,"(c) Joinder of Federal Law Claims and State Law Claims.—(1) If a civil action includes—"],[1,"(A) a claim arising under the Constitution, laws, or treaties of the United States (within the meaning of section 1331 of this title), and"],[1,"(B) a claim not within the original or supplemental jurisdiction of the district court or a claim that has been made nonremovable by statute,"],[0,"the entire action may be removed if the action would be removable without the inclusion of the claim described in subparagraph (B)."],[0,"(2) Upon removal of an action described in paragraph (1), the district court shall sever from the action all claims described in paragraph (1)(B) and shall remand the severed claims to the State court from which the action was removed. Only defendants against whom a claim described in paragraph (1)(A) has been asserted are required to join in or consent to the removal under paragraph (1)."],[0,"(d) Actions Against Foreign States.—Any civil action brought in a State court against a foreign state as defined in section 1603(a) of this title may be removed by the foreign state to the district court of the United States for the district and division embracing the place where such action is pending. Upon removal the action shall be tried by the court without jury. Where removal is based upon this subsection, the time limitations of section 1446(b) of this chapter may be enlarged at any time for cause shown."],[0,"(e) Multiparty, Multiforum Jurisdiction.—(1) Notwithstanding the provisions of subsection (b) of this section, a defendant in a civil action in a State court may remove the action to the district court of the United States for the district and division embracing the place where the action is pending if—"],[1,"(A) the action could have been brought in a United States district court under section 1369 of this title; or"],[1,"(B) the defendant is a party to an action which is or could have been brought, in whole or in part, under section 1369 in a United States district court and arises from the same accident as the action in State court, even if the action to be removed could not have been brought in a district court as an original matter."],[0,"The removal of an action under this subsection shall be made in accordance with section 1446 of this title, except that a notice of removal may also be filed before trial of the action in State court within 30 days after the date on which the defendant first becomes a party to an action under section 1369 in a United States district court that arises from the same accident as the action in State court, or at a later time with leave of the district court."],[0,"(2) Whenever an action is removed under this subsection and the district court to which it is removed or transferred under section 1407(j) 1 has made a liability determination requiring further proceedings as to damages, the district court shall remand the action to the State court from which it had been removed for the determination of damages, unless the court finds that, for the convenience of parties and witnesses and in the interest of justice, the action should be retained for the determination of damages."],[0,"(3) Any remand under paragraph (2) shall not be effective until 60 days after the district court has issued an order determining liability and has certified its intention to remand the removed action for the determination of damages. An appeal with respect to the liability determination of the district court may be taken during that 60-day period to the court of appeals with appellate jurisdiction over the district court. In the event a party files such an appeal, the remand shall not be effective until the appeal has been finally disposed of. Once the remand has become effective, the liability determination shall not be subject to further review by appeal or otherwise."],[0,"(4) Any decision under this subsection concerning remand for the determination of damages shall not be reviewable by appeal or otherwise."],[0,"(5) An action removed under this subsection shall be deemed to be an action under section 1369 and an action in which jurisdiction is based on section 1369 of this title for purposes of this section and sections 1407, 1697, and 1785 of this title."],[0,"(6) Nothing in this subsection shall restrict the authority of the district court to transfer or dismiss an action on the ground of inconvenient forum."],[0,"(f) Derivative Removal Jurisdiction.—The court to which a civil action is removed under this section is not precluded from hearing and determining any claim in such civil action because the State court from which such civil action is removed did not have jurisdiction over that claim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1441?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4","1":"16"}},{"t":"usc","label":"28 U.S.C. § 1446","url":"https://www.law.cornell.edu/uscode/text/28/1446","subs":["(b)(3)"],"stext":{"head":"§1446. Procedure for removal of civil actions","paras":[[0,"(a) Generally.—A defendant or defendants desiring to remove any civil action from a State court shall file in the district court of the United States for the district and division within which such action is pending a notice of removal signed pursuant to Rule 11 of the Federal Rules of Civil Procedure and containing a short and plain statement of the grounds for removal, together with a copy of all process, pleadings, and orders served upon such defendant or defendants in such action."],[0,"(b) Requirements; Generally.—(1) The notice of removal of a civil action or proceeding shall be filed within 30 days after the receipt by the defendant, through service or otherwise, of a copy of the initial pleading setting forth the claim for relief upon which such action or proceeding is based, or within 30 days after the service of summons upon the defendant if such initial pleading has then been filed in court and is not required to be served on the defendant, whichever period is shorter."],[0,"(2)(A) When a civil action is removed solely under section 1441(a), all defendants who have been properly joined and served must join in or consent to the removal of the action."],[0,"(B) Each defendant shall have 30 days after receipt by or service on that defendant of the initial pleading or summons described in paragraph (1) to file the notice of removal."],[0,"(C) If defendants are served at different times, and a later-served defendant files a notice of removal, any earlier-served defendant may consent to the removal even though that earlier-served defendant did not previously initiate or consent to removal."],[0,"(3) Except as provided in subsection (c), if the case stated by the initial pleading is not removable, a notice of removal may be filed within thirty days after receipt by the defendant, through service or otherwise, of a copy of an amended pleading, motion, order or other paper from which it may first be ascertained that the case is one which is or has become removable."],[0,"(c) Requirements; Removal Based on Diversity of Citizenship.—(1) A case may not be removed under subsection (b)(3) on the basis of jurisdiction conferred by section 1332 more than 1 year after commencement of the action, unless the district court finds that the plaintiff has acted in bad faith in order to prevent a defendant from removing the action."],[0,"(2) If removal of a civil action is sought on the basis of the jurisdiction conferred by section 1332(a), the sum demanded in good faith in the initial pleading shall be deemed to be the amount in controversy, except that—"],[1,"(A) the notice of removal may assert the amount in controversy if the initial pleading seeks—"],[2,"(i) nonmonetary relief; or"],[2,"(ii) a money judgment, but the State practice either does not permit demand for a specific sum or permits recovery of damages in excess of the amount demanded; and"],[1,"(B) removal of the action is proper on the basis of an amount in controversy asserted under subparagraph (A) if the district court finds, by the preponderance of the evidence, that the amount in controversy exceeds the amount specified in section 1332(a)."],[0,"(3)(A) If the case stated by the initial pleading is not removable solely because the amount in controversy does not exceed the amount specified in section 1332(a), information relating to the amount in controversy in the record of the State proceeding, or in responses to discovery, shall be treated as an \"other paper\" under subsection (b)(3)."],[0,"(B) If the notice of removal is filed more than 1 year after commencement of the action and the district court finds that the plaintiff deliberately failed to disclose the actual amount in controversy to prevent removal, that finding shall be deemed bad faith under paragraph (1)."],[0,"(d) Notice to Adverse Parties and State Court.—Promptly after the filing of such notice of removal of a civil action the defendant or defendants shall give written notice thereof to all adverse parties and shall file a copy of the notice with the clerk of such State court, which shall effect the removal and the State court shall proceed no further unless and until the case is remanded."],[0,"(e) Counterclaim in 337 Proceeding.—With respect to any counterclaim removed to a district court pursuant to section 337(c) of the Tariff Act of 1930, the district court shall resolve such counterclaim in the same manner as an original complaint under the Federal Rules of Civil Procedure, except that the payment of a filing fee shall not be required in such cases and the counterclaim shall relate back to the date of the original complaint in the proceeding before the International Trade Commission under section 337 of that Act."],[0,"(g) 1 Where the civil action or criminal prosecution that is removable under section 1442(a) is a proceeding in which a judicial order for testimony or documents is sought or issued or sought to be enforced, the 30-day requirement of subsection (b) of this section and paragraph (1) of section 1455(b) is satisfied if the person or entity desiring to remove the proceeding files the notice of removal not later than 30 days after receiving, through service, notice of any such proceeding."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1446?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4","1":"22"}},{"t":"usc","label":"28 U.S.C. § 1447","url":"https://www.law.cornell.edu/uscode/text/28/1447","subs":["(c)","(e)"],"stext":{"head":"§1447. Procedure after removal generally","paras":[[0,"(a) In any case removed from a State court, the district court may issue all necessary orders and process to bring before it all proper parties whether served by process issued by the State court or otherwise."],[0,"(b) It may require the removing party to file with its clerk copies of all records and proceedings in such State court or may cause the same to be brought before it by writ of certiorari issued to such State court."],[0,"(c) A motion to remand the case on the basis of any defect other than lack of subject matter jurisdiction must be made within 30 days after the filing of the notice of removal under section 1446(a). If at any time before final judgment it appears that the district court lacks subject matter jurisdiction, the case shall be remanded. An order remanding the case may require payment of just costs and any actual expenses, including attorney fees, incurred as a result of the removal. A certified copy of the order of remand shall be mailed by the clerk to the clerk of the State court. The State court may thereupon proceed with such case."],[0,"(d) An order remanding a case to the State court from which it was removed is not reviewable on appeal or otherwise, except that an order remanding a case to the State court from which it was removed pursuant to section 1442 or 1443 of this title shall be reviewable by appeal or otherwise."],[0,"(e) If after removal the plaintiff seeks to join additional defendants whose joinder would destroy subject matter jurisdiction, the court may deny joinder, or permit joinder and remand the action to the State court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1447?type=usc&year=mostrecent&link-type=html"},"by":{"0":"16","1":"11, 16-17, 19-22, 24, 30, 44, 44","2":"9, 13"},"q":[{"src":"brief","b":0,"text":"[i]f at any time before final judgment it appears that the district court lacks subject matter jurisdiction, the case shall be remanded,","cite":"28 U.S.C. § 1447(c)"},{"src":"brief","b":1,"text":"[i]f at any time before final judgment it appears that the district court lacks subject matter jurisdiction, the case shall be remanded.","cite":"28 U.S.C. § 1447(c)"},{"src":"brief","b":2,"text":"at any time before final judgment.","cite":"28 U.S.C. § 1447(c)"}]},{"t":"rule","label":"Fed. R. Civ. P. 21","url":"https://www.law.cornell.edu/rules/frcp/rule_21","by":{"0":"23","2":"16, 19"}},{"t":"rule","label":"Fed. R. Civ. P. 30","url":"https://www.law.cornell.edu/rules/frcp/rule_30","by":{"0":"28"}},{"t":"rule","label":"Fed. R. Civ. P. 34","url":"https://www.law.cornell.edu/rules/frcp/rule_34","by":{"0":"28"}},{"t":"case","label":"American Car & Foundry Co. v. Kettelhake","cite":"236 U.S. 311","y":1915,"id":"scdb/1914-219","sc":1,"by":{"1":"22"}},{"t":"case","label":"American Fire & Cas. Co. v. Finn","cite":"341 U.S. 6","y":1951,"id":"scdb/1950-055","sc":1,"by":{"1":"22","2":"8"},"q":[{"src":"brief","b":1,"text":"[t]he posture of this case even at the time of judgment also barred federal jurisdiction. A Texas citizen was and remained a party defendant.","cite":"341 U.S. 6, 17"}]},{"t":"case","label":"Atlas Glob. Grp., L.P. v. Grupo Dataflux","cite":"312 F.3d 168","y":2002,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/312/168/","by":{"1":"33"},"q":[{"src":"brief","b":1,"text":"the so-called ‘waste’ of judicial resources that occurs when we dismiss a case for lack of jurisdiction is the price that we pay for federalism.","cite":"312 F.3d 168, 178"}]},{"t":"case","label":"Buck’s Stove & Range Co. v. American Fed’n of Labor","cite":"219 U.S. 581","y":1911,"id":"scdb/1910-184","sc":1,"by":{"1":"25"}},{"t":"case","label":"Caribe Chem Distribs., Corp. v. Southern Agric. Insecticides, Inc.","cite":"96 F.4th 25","y":2024,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.4th/96/25/","by":{"1":"22"}},{"t":"case","label":"Caterpillar Inc. v. Williams","cite":"482 U.S. 386","y":1987,"id":"1986/86-526","sc":1,"by":{"1":"18"}},{"t":"case","label":"Catlin v. United States","cite":"324 U.S. 229","y":1945,"id":"scdb/1944-071","sc":1,"by":{"1":"21"}},{"t":"case","label":"Chicago, R.I. & P. Ry. Co. v. Schwyhart","cite":"227 U.S. 184","y":1913,"id":"scdb/1912-083","sc":1,"by":{"1":"16, 45"},"q":[{"src":"brief","b":1,"text":"he has an absolute right to enforce it, whatever the reason that makes him wish to assert the right.","cite":"227 U.S. 184, 193"},{"src":"brief","b":1,"text":"has an absolute right to enforce it, whatever the reason that makes him wish to assert the right.","cite":"227 U.S. at 193"}]},{"t":"case","label":"Chicago, R.I. & P. Ry. Co. v. Whiteaker","cite":"239 U.S. 421","y":1915,"id":"scdb/1915-005","sc":1,"by":{"1":"16"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"are but steps towards [the] final judgment in which they will merge.","cite":"337 U.S. 541, 546"}]},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"by":{"1":"40"},"q":[{"src":"brief","b":1,"text":"a court of review, not of first view.","cite":"544 U.S. 709, 718 n.7"}]},{"t":"case","label":"Deposit Guar. Nat’l Bank v. Roper","cite":"445 U.S. 326","y":1980,"id":"1979/78-904","sc":1,"by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"substantive claims become moot in the Art. III sense, by settlement of all personal claims for example, the court retains no jurisdiction over the controversy of the individual plaintiffs.","cite":"445 U.S. 326, 332"}]},{"t":"case","label":"Dupree v. Younger","cite":"598 U.S. 729","y":2023,"id":"2022/22-210","sc":1,"by":{"1":"21"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"not dispose of the whole case.","cite":"598 U. S. 729, 734"}]},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs., Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"by":{"1":"4, 14-15, 17, 28"}},{"t":"case","label":"F.F.P. Operating Partners, L.P. v. Duenez","cite":"237 S.W.3d 680","y":2007,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/237/680/","by":{"1":"46"}},{"t":"case","label":"Gelboim v. Bank of Am. Corp.","cite":"574 U.S. 405","y":2015,"id":"2014/13-1174","sc":1,"by":{"1":"21, 33"},"q":[{"src":"brief","b":1,"text":"specifically to avoid the possible injustice of delaying judgment on a distinctly separate claim pending adjudication of the entire case.","cite":"574 U.S. at 409"}]},{"t":"case","label":"Great N. Ry. Co. v. Alexander","cite":"246 U.S. 276","y":1918,"id":"scdb/1917-082","sc":1,"by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"the voluntary dismissal or nonsuit by [the plaintiff ] of a party or of parties defendant.","cite":"246 U.S. 276, 281"}]},{"t":"case","label":"Greenlaw v. United States","cite":"554 U.S. 237","y":2008,"id":"2007/07-330","sc":1,"by":{"1":"41"},"q":[{"src":"brief","b":1,"text":"rely on the parties to frame the issues for decision.","cite":"554 U.S. 237, 243"}]},{"t":"case","label":"Healy v. Ratta","cite":"292 U.S. 263","y":1934,"id":"scdb/1933-157","sc":1,"by":{"1":"17"},"q":[{"src":"brief","b":1,"text":"Due regard for the rightful independence of state governments, which should actuate federal courts, requires that they scrupulously confine their own jurisdiction to the precise limits which the statute has defined.","cite":"292 U.S. 263, 270"}]},{"t":"case","label":"Illinois Cent. R.R. Co. v. Sheegog","cite":"215 U.S. 308","y":1909,"id":"scdb/1909-035","sc":1,"by":{"1":"16"}},{"t":"case","label":"Italian Cowboy Partners, Ltd. v. Prudential Ins. Co.","cite":"341 S.W.3d 323","y":2011,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/341/323/","by":{"1":"10"}},{"t":"case","label":"Izumi Seimitsu Kogyo Kabushiki Kaisha v. U.S. Philips Corp.","cite":"510 U.S. 27","y":1993,"id":"1993/92-1123","sc":1,"by":{"1":"38"}},{"t":"case","label":"Junk v. Terminix Int’l Co.","cite":"628 F.3d 439","y":2010,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/628/439/","by":{"1":"36"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"by":{"1":"14, 36"},"q":[{"src":"brief","b":1,"text":"[f ]ederal courts are courts of limited jurisdiction. They possess only that power authorized by Constitution and statute, which is not to be expanded by judicial decree.","cite":"511 U.S. 375, 377"},{"src":"brief","b":1,"text":"presume[ ] that a cause lies outside [their] limited jurisdiction, and the burden of establishing the contrary rests upon the party asserting jurisdiction.","cite":"511 U.S. at 377"},{"src":"opinion","who":"Justice Thomas, concurring","text":"aFegdeeralPcourrotsoarfe Pending courts of limited Pjuruisdbicltiiocn.a","cite":"511 U. S. 375, 377"}]},{"t":"case","label":"Kramer v. Lewisville Mem’l Hosp.","cite":"858 S.W.2d 397","y":1993,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/858/397/","by":{"1":"46"},"q":[{"src":"brief","b":1,"text":"where the inextricable combination of joint tortfeasors combines to cause harm in a manner where individual responsibility cannot be fixed.","cite":"858 S.W.2d 397, 405"}]},{"t":"case","label":"Lexecon Inc. v. Milberg Weiss Bershad Hynes & Lerach","cite":"523 U.S. 26","y":1998,"id":"1997/96-1482","sc":1,"by":{"1":"19, 22, 24, 29-31, 35, 37","2":"8, 9"},"q":[{"src":"brief","b":1,"text":"would be to allow uncorrected defiance of a categorical congressional judgment to become its own justification.","cite":"523 U.S. 26, 42"},{"src":"brief","b":1,"text":"give effect to this plain command.","cite":"523 U.S. at 35"},{"src":"argument","who":"Justice Gorsuch","text":"And -- and what do we do about Lexecon, where it was two federal district courts -- we weren't even talking about state court -- and a judgment was entered and there was no argument that the judgment in one district court's better than a judgment in another district court, and we completely sent it back to start over because the plaintiff's choice of forum was denied?"},{"src":"argument","who":"Ms. Harrington","text":"Well, it wasn't -- I'll start with the second if that's all right. In Lexecon --"},{"src":"argument","who":"Ms. Harrington","text":"So, for Lexecon, the problem there was that there -- the -- the problem hadn't been cured by the time of final judgment. The district court that entered the judgment never had the authority to do that."}]},{"t":"case","label":"Lincoln Prop. Co. v. Roche","cite":"546 U.S. 81","y":2005,"id":"2005/04-712","sc":1,"by":{"1":"18, 44"},"q":[{"src":"brief","b":1,"text":"is unambiguous and it is not amenable to judicial enlargement.","cite":"546 U.S. at 94"}]},{"t":"case","label":"Louisville & N.R.R. Co. v. Mottley","cite":"211 U.S. 149","y":1908,"id":"scdb/1908-012","sc":1,"by":{"1":"3"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Manning","cite":"578 U.S. 374","y":2016,"id":"2015/14-1132","sc":1,"by":{"1":"17, 36, 48"},"q":[{"src":"brief","b":1,"text":"maintain the constitutional balance between state and federal judiciaries.","cite":"578 U.S. 374, 389-90"},{"src":"brief","b":1,"text":"the constitutional balance between state and federal judiciaries.","cite":"578 U.S. at 390"}]},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"by":{"1":"41"},"q":[{"src":"brief","b":1,"text":"was never presented to any lower court and is therefore forfeited.","cite":"577 U.S. 27, 37"}]},{"t":"case","label":"Pennington v. Singleton","cite":"606 S.W.2d 682","y":1980,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/606/682/","by":{"1":"10"}},{"t":"case","label":"Poulos v. Naas Foods, Inc.","cite":"959 F.2d 69","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/959/69/","by":{"1":"22"}},{"t":"case","label":"Powers v. Chesapeake & O. Ry. Co.","cite":"169 U.S. 92","y":1898,"id":"scdb/1897-061","sc":1,"by":{"1":"22"}},{"t":"case","label":"Quackenbush v. Allstate Ins. Co.","cite":"517 U.S. 706","y":1996,"id":"1995/95-244","sc":1,"by":{"1":"21"}},{"t":"case","label":"Rivers v. Guerrero","cite":"605 U.S. 443","y":2025,"id":"2024/23-1345","sc":1,"by":{"1":"40"}},{"t":"case","label":"Ruhrgas AG v. Marathon Oil Co.","cite":"526 U.S. 574","y":1999,"id":"1998/98-470","sc":1,"by":{"1":"17, 37"},"q":[{"src":"brief","b":1,"text":"[s]ubject-matter limitations on federal jurisdiction serve institutional interests. They keep the federal courts within the bounds the Constitution and Congress have prescribed.","cite":"526 U.S. 574, 583"},{"src":"brief","b":1,"text":"federal and state courts are complementary systems for administering justice in our Nation. Cooperation and comity, not competition and conflict, are essential to the federal design.","cite":"526 U.S. at 586"}]},{"t":"case","label":"Stanley v. City of Sanford","cite":"145 S. Ct. 2058","y":2025,"id":"2024/23-997","sc":1,"by":{"1":"39"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"by":{"1":"14, 19, 48"},"q":[{"src":"brief","b":1,"text":"when it has no jurisdiction to do so is, by very definition, for a court to act ultra vires.","cite":"523 U.S. at 101"},{"src":"opinion","who":"Justice Thomas, concurring","text":"The requirement that jurisdiction be established as a threshold matter spring[s] from the nature and limits of the judicial power of the United States and is infexible and without exception.","cite":"523 U. S., at 94"}]},{"t":"case","label":"Swint v. Chambers Cnty. Comm’n","cite":"514 U.S. 35","y":1995,"id":"1994/93-1636","sc":1,"by":{"1":"21"}},{"t":"case","label":"Syngenta Crop Prot., Inc. v. Henson","cite":"537 U.S. 28","y":2002,"id":"2002/01-757","sc":1,"by":{"1":"17"}},{"t":"case","label":"United States v. Sineneng-Smith","cite":"590 U.S. 371","y":2020,"id":"2019/19-67","sc":1,"by":{"1":"41"}},{"t":"case","label":"Waetzig v. Halliburton Energy Servs., Inc.","cite":"145 S. Ct. 690","y":2025,"id":"2024/23-971","sc":1,"by":{"1":"41"},"q":[{"src":"brief","b":1,"text":"the relevant arguments have been preserved.","cite":"145 S. Ct. 690, 701"}]},{"t":"case","label":"Whitcomb v. Smithson","cite":"175 U.S. 635","y":1900,"id":"scdb/1899-095","sc":1,"by":{"1":"22-23"},"q":[{"src":"brief","b":1,"text":"did not operate to make the cause then removable.","cite":"175 U.S. at 638"}]},{"t":"case","label":"Wilkinson v. Shackelford","cite":"478 F.3d 957","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/478/957/","by":{"1":"36"}},{"t":"case","label":"Wilson v. Republic Iron & Steel Co.","cite":"257 U.S. 92","y":1921,"id":"scdb/1921-013","sc":1,"by":{"1":"16"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"by":{"1":"38-39"}},{"t":"usc","label":"28 U.S.C. § 1407","url":"https://www.law.cornell.edu/uscode/text/28/1407","subs":["(a)"],"stext":{"head":"§1407. Multidistrict litigation","paras":[[0,"(a) When civil actions involving one or more common questions of fact are pending in different districts, such actions may be transferred to any district for coordinated or consolidated pretrial proceedings. Such transfers shall be made by the judicial panel on multidistrict litigation authorized by this section upon its determination that transfers for such proceedings will be for the convenience of parties and witnesses and will promote the just and efficient conduct of such actions. Each action so transferred shall be remanded by the panel at or before the conclusion of such pretrial proceedings to the district from which it was transferred unless it shall have been previously terminated: Provided, however, That the panel may separate any claim, cross-claim, counter-claim, or third-party claim and remand any of such claims before the remainder of the action is remanded."],[0,"(b) Such coordinated or consolidated pretrial proceedings shall be conducted by a judge or judges to whom such actions are assigned by the judicial panel on multidistrict litigation. For this purpose, upon request of the panel, a circuit judge or a district judge may be designated and assigned temporarily for service in the transferee district by the Chief Justice of the United States or the chief judge of the circuit, as may be required, in accordance with the provisions of chapter 13 of this title. With the consent of the transferee district court, such actions may be assigned by the panel to a judge or judges of such district. The judge or judges to whom such actions are assigned, the members of the judicial panel on multidistrict litigation, and other circuit and district judges designated when needed by the panel may exercise the powers of a district judge in any district for the purpose of conducting pretrial depositions in such coordinated or consolidated pretrial proceedings."],[0,"(c) Proceedings for the transfer of an action under this section may be initiated by—"],[1,"(i) the judicial panel on multidistrict litigation upon its own initiative, or"],[1,"(ii) motion filed with the panel by a party in any action in which transfer for coordinated or consolidated pretrial proceedings under this section may be appropriate. A copy of such motion shall be filed in the district court in which the moving party's action is pending."],[0,"The panel shall give notice to the parties in all actions in which transfers for coordinated or consolidated pretrial proceedings are contemplated, and such notice shall specify the time and place of any hearing to determine whether such transfer shall be made. Orders of the panel to set a hearing and other orders of the panel issued prior to the order either directing or denying transfer shall be filed in the office of the clerk of the district court in which a transfer hearing is to be or has been held. The panel's order of transfer shall be based upon a record of such hearing at which material evidence may be offered by any party to an action pending in any district that would be affected by the proceedings under this section, and shall be supported by findings of fact and conclusions of law based upon such record. Orders of transfer and such other orders as the panel may make thereafter shall be filed in the office of the clerk of the district court of the transferee district and shall be effective when thus filed. The clerk of the transferee district court shall forthwith transmit a certified copy of the panel's order to transfer to the clerk of the district court from which the action is being transferred. An order denying transfer shall be filed in each district wherein there is a case pending in which the motion for transfer has been made."],[0,"(d) The judicial panel on multidistrict litigation shall consist of seven circuit and district judges designated from time to time by the Chief Justice of the United States, no two of whom shall be from the same circuit. The concurrence of four members shall be necessary to any action by the panel."],[0,"(e) No proceedings for review of any order of the panel may be permitted except by extraordinary writ pursuant to the provisions of title 28, section 1651, United States Code. Petitions for an extraordinary writ to review an order of the panel to set a transfer hearing and other orders of the panel issued prior to the order either directing or denying transfer shall be filed only in the court of appeals having jurisdiction over the district in which a hearing is to be or has been held. Petitions for an extraordinary writ to review an order to transfer or orders subsequent to transfer shall be filed only in the court of appeals having jurisdiction over the transferee district. There shall be no appeal or review of an order of the panel denying a motion to transfer for consolidated or coordinated proceedings."],[0,"(f) The panel may prescribe rules for the conduct of its business not inconsistent with Acts of Congress and the Federal Rules of Civil Procedure."],[0,"(g) Nothing in this section shall apply to any action in which the United States or a State is a complainant arising under the antitrust laws. \"Antitrust laws\" as used herein include those acts referred to in the Act of October 15, 1914, as amended (38 Stat. 730; 15 U.S.C. 12), and also include the Act of June 19, 1936 (49 Stat. 1526; 15 U.S.C. 13, 13a, and 13b) and the Act of September 26, 1914, as added March 21, 1938 (52 Stat. 116, 117; 15 U.S.C. 56)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1407?type=usc&year=mostrecent&link-type=html"},"by":{"1":"29-30"},"q":[{"src":"brief","b":1,"text":"shall be remanded by the [MDL] panel at or before the conclusion of such pretrial proceedings to the district from which it was transferred","cite":"28 U.S.C. § 1407(a)"}]},{"t":"case","label":"Bolden v. Brooks","cite":"138 F. App’x 601","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/138/601/","by":{"2":"4"}},{"t":"case","label":"Bowen Eng'g Corp. v. Pac. Indem. Co.","cite":"2014 WL 6908747","y":2014,"court":"D. Kan. Dec. 8","by":{"2":"5"}},{"t":"case","label":"de Fernandez v. CMA CGM S.A.","cite":"2024 WL 3580949","y":2024,"court":"S.D. Fla. July 30","by":{"2":"5"}},{"t":"case","label":"Finn v. Am. Fire & Cas. Co.","cite":"207 F.2d 113","y":1953,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/207/113/","by":{"2":"8"},"q":[{"src":"brief","b":2,"text":"the federal court could not have original jurisdiction of the suit even in the posture it had at the time of judgment.","cite":"207 F.2d 113, 114"}]},{"t":"case","label":"Firestone Tire & Rubber Co. v. Risjord","cite":"449 U.S. 368","y":1981,"id":"1980/79-1420","sc":1,"by":{"2":"3"},"q":[{"src":"brief","b":2,"text":"serve[] the important purpose of promoting efficient judicial administration.","cite":"449 U.S. 368, 374"}]},{"t":"case","label":"Iloominate Media, Inc. v. CAIR Fla., Inc.","cite":"841 F. App’x 132","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/841/132/","by":{"2":"4"}},{"t":"case","label":"Kitchen v. Heyns","cite":"802 F.3d 873","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/802/873/","by":{"2":"5"}},{"t":"case","label":"Marcello v. Maine","cite":"2006 WL 3804891","y":2006,"court":"D. Me. Dec. 22","by":{"2":"5"}},{"t":"case","label":"Publicker Indus., Inc. v. Roman Ceramics Corp.","cite":"603 F.2d 1065","y":1979,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/603/1065/","by":{"2":"19"}},{"t":"case","label":"Tayal v. Bank of N.Y. Mellon","cite":"2022 WL 563240","y":2022,"court":"4th Cir. Feb. 24","by":{"2":"4"}},{"t":"case","label":"Tungsten Parts Wyo., Inc. v. Omanoff","cite":"2023 WL 2630417","y":2023,"court":"D. Wyo. Feb. 27","by":{"2":"5"}},{"t":"case","label":"Wagle v. Mich. Dep’t of Corr.","cite":"2012 WL 4795638","y":2012,"court":"E.D. Mich. Oct. 9","by":{"2":"5"}},{"t":"case","label":"Petition, Caterpillar Inc. v. Lewis","cite":"1996 WL 33413834","y":1996,"court":"U.S. filed Feb. 8","by":{"2":"12"}}]};